package com.flippingfriend.companion;
import java.util.ArrayList; import java.util.List;
/** Pure fail-closed interpretation using shared plausibility semantics on both measured legs. */
final class BuyReplacementQuantityFillViabilityEvaluator {
 BuyReplacementQuantityFillViabilityAssessment evaluate(BuyReplacementQuantityFillEvaluationSet s,long at){if(s==null||at<s.getEvaluatedAt()||s.getEvaluatedAt()+CompanionBuyReplacementReadinessPolicy.MAX_INPUT_AGE_SECONDS<at||s.getInputs()==null||s.getInputs().isEmpty()||s.getEvaluations()==null||s.getInputs().size()!=s.getEvaluations().size())return null;List<BuyReplacementQuantityFillEvaluation> complete=new ArrayList<>(s.getEvaluations().size());List<BuyReplacementQuantityFillViableCandidate> viable=new ArrayList<>();for(int i=0;i<s.getEvaluations().size();i++){BuyReplacementQuantityFillInput x=s.getInputs().get(i);BuyReplacementQuantityFillEvaluation e=s.getEvaluations().get(i);if(!valid(x,e,s))return null;complete.add(e);if(plausible(e.getBuyProbability(),e.getBuyExpectedHours())&&plausible(e.getSellProbability(),e.getSellExpectedHours()))viable.add(new BuyReplacementQuantityFillViableCandidate(e));}return new BuyReplacementQuantityFillViabilityAssessment(s,viable.isEmpty()?BuyReplacementQuantityFillViabilityOutcome.NOT_VIABLE:BuyReplacementQuantityFillViabilityOutcome.VIABLE,complete,viable,at);}
 private static boolean plausible(double p,double h){return p>0&&Double.isFinite(h);} private static boolean valid(BuyReplacementQuantityFillInput x,BuyReplacementQuantityFillEvaluation e,BuyReplacementQuantityFillEvaluationSet s){return x!=null&&e!=null&&e.getBuyOffsetIndex()==x.getBuyOffsetIndex()&&e.getSellOffsetIndex()==x.getSellOffsetIndex()&&e.getBuyPrice()==x.getBuyPrice()&&e.getSellPrice()==x.getSellPrice()&&e.getFillableQuantity()==s.getExactRemainderQuantity()&&e.getFillableQuantity()==x.getFillableQuantity()&&e.getQuantity()==x.getQuantity()&&e.getSizeGridIndex()==x.getSizeGridIndex()&&Double.compare(e.getSizeShare(),x.getSizeShare())==0&&Double.compare(e.getKellyFraction(),x.getKellyFraction())==0&&Double.compare(e.getExpectedProfit(),x.getExpectedProfit())==0&&e.getWorstLoss()==x.getWorstLoss()&&measure(e.getBuyProbability(),e.getBuyExpectedHours(),e.getBuyUnitsPerHour(),e.getBuyWaitHours())&&measure(e.getSellProbability(),e.getSellExpectedHours(),e.getSellUnitsPerHour(),e.getSellWaitHours());} private static boolean measure(double p,double h,double u,double w){return Double.isFinite(p)&&p>=0&&p<=1&&!Double.isNaN(h)&&h>=0&&Double.isFinite(u)&&u>=0&&!Double.isNaN(w)&&w>=0;}
}
